-- Thread 1 (sort 342): the-days-of-noach-and-the-watcher-rebellion-judgment-pattern-in-1-enoch-and-jubilees
INSERT INTO cross_reference_threads (slug, title, summary_md, anchor_verse_id_start, anchor_verse_id_end, tier_required, sort_order)
SELECT 'the-days-of-noach-and-the-watcher-rebellion-judgment-pattern-in-1-enoch-and-jubilees',
       'The days of Noach (Noah) and the Watcher-rebellion judgment-pattern — 1 Enoch 10, 65, 67 + Jubilees 5 (FRAMEWORK-MAJOR)',
       'Matt 24:37-39''s *as the days of Noach (Noah) were, so shall also the coming of the Son of Adam be* — the King walking the substantial-Genesis 6:1-13 Watcher-rebellion-substance the substantial Adam-and-the-tares-architecture preserves, the substance the apostle-Yehudah (Jude) quotes at Jude 14-15 from 1 Enoch and the apostle-Kefa (Peter) walks at 2 Peter 2:5 + 2 Peter 3:3-7 — read against the wisdom-stream''s direct articulation of the antediluvian-judgment-architecture. Five moves: 1 Enoch 10:2 names THE direct wisdom-stream verbal-anchor for the proclamation-to-Noach (Noah) substance (*Go to Noach (Noah) and tell him... reveal to him the end that is approaching: that the whole earth will be destroyed*); 1 Enoch 65:11 names the substantial-three-category-judgment-architecture (*the Most High shall send His punishment upon the sinners and upon the fallen angels, and upon their children* — sinners, Watchers, and the Nephilim (giants) corruption of the substantial-flesh-substance the Watchers walked-the-substantial-creation-order against); 1 Enoch 67:1 names the consummation-of-the-punishment-of-the-fallen-angels substance (*they shall be led off to the abyss of fire*) tying Matt 24:39''s *took them all away* substance to the substantial-judgment-substance, NOT the substantial-modern-Christian-pre-tribulation-rapture-rescue-substance; Jubilees 5:2 names the lawlessness-increased-and-all-flesh-corrupted-its-way substance — the same Greek-anomia / torahlessness substance the King walks at Matt 24:12 (*because iniquity (anomia, torahlessness) shall abound, the love of many shall wax cold*) ties-forward-to; Jubilees 5:19 names the no-man''s-person-was-accepted-save-Noach (Noah) substance the substantial *one shall be taken, and the other left* pattern at Matt 24:40-41 walks-the-architecture-of, the substance the substantial-Lukan-parallel of Luke 17:34-37 confirms (the disciples'' *where, Lord?* receiving *wheresoever the body is, thither will the eagles be gathered together* — the substantial *taken* substance walks-into-the-substantial-judgment, NOT the substantial-rescue). FRAMEWORK-MAJOR. The framework reads the cluster as the wisdom-stream''s direct corroboration that the days-of-Noach (Noah) pattern is the substantial-Watcher-rebellion-and-judgment-pattern the substantial-end-of-the-age recapitulates — corruption-of-the-substantial-flesh-substance, lawlessness-on-the-earth, unawareness-among-the-substantial-people-the-substantial-judgment-substance-takes-away, preservation-of-the-substantial-Father''s-chosen.',
       sv.verse_id, ev.verse_id, 'complete_study', 342
  FROM _s156_xref_lookup sv, _s156_xref_lookup ev
 WHERE sv.edition_slug = 'canon' AND sv.book_slug = 'matthew' AND sv.chapter_number = 24 AND sv.verse_number = 37
   AND ev.edition_slug = 'canon' AND ev.book_slug = 'matthew' AND ev.chapter_number = 24 AND ev.verse_number = 39
ON CONFLICT (slug) DO NOTHING;

-- Thread 2 (sort 343): the-gathering-of-the-elect-from-the-four-winds-in-1-enochs-animal-apocalypse-and-parables
INSERT INTO cross_reference_threads (slug, title, summary_md, anchor_verse_id_start, anchor_verse_id_end, tier_required, sort_order)
SELECT 'the-gathering-of-the-elect-from-the-four-winds-in-1-enochs-animal-apocalypse-and-parables',
       'The gathering of the elect from the four winds — 1 Enoch''s Parables (ch 57, 61) and Animal Apocalypse (ch 90) (FRAMEWORK-MAJOR)',
       'Matt 24:27-31''s framework-major substance — the *lightning out of the east, and shineth even unto the west* substance at v.27 ruling-out the substantial-secret-rapture-substance; the *Son of Adam coming in the clouds of heaven with power and great glory* substance at v.30 (where the Greek does NOT carry the *hōs* / *homoion* comparative — the kaph-comparative narrow-rule preserved only at Daniel 7:13 + Revelation 1:13 + Revelation 14:14 per Red Line #12); the substantial *great sound of a trumpet* + *gather together his elect from the four winds, from one end of heaven to the other* substance at v.31 — THE central Red Line #11 four-winds-gathering verse, anchoring the substantial-paternal-blood-remnant-of-the-twelve-tribes ingathering the prophets walked. Read against the wisdom-stream''s direct articulation of the cosmic-public-coming + gathering-of-the-sheep architecture in 1 Enoch''s Parables and Animal Apocalypse. Four moves: 1 Enoch 57:1 names THE direct wisdom-stream verbal-anchor for the *coming on the winds from the east, and from the west to the south* substance the King walks at Matt 24:27 (the substantial-public-visible-second-coming substance against the substantial-modern-dispensational-Christian-eschatology); 1 Enoch 57:2 names THE direct verbal-anchor for the *from one end of heaven to the other* substance the King walks at Matt 24:31 — the substantial-cosmic-sound-from-end-to-end the wisdom-stream had named at the Parables; 1 Enoch 61:5 names the gathering-of-the-substance-destroyed-and-devoured substance (those-destroyed-by-the-desert, devoured-by-the-beasts, devoured-by-the-fish-of-the-sea) the Father preserves-and-returns at the substantial-day-of-the-Elect-One — the substantial-architecture the substantial-gathering-of-the-elect-from-the-four-winds operates within; 1 Enoch 90:10 names the substantial-Animal-Apocalypse-substance of the substantial-sheep-gathered-together-to-the-great-horn — the substantial-paternal-blood-remnant-of-Yashar''el (Israel) gathered-by-the-Lord-of-the-sheep, with 90:17''s substantial-Lord-of-the-sheep bringing-all-the-sheep-into-the-new-house threaded-into the cross-reference note per the substantial-ingathering-of-all-twelve-tribes substance Ezekiel 37:15-28 walked. FRAMEWORK-MAJOR per Red Line #11. The framework reads the cluster as the substantial-direct-wisdom-stream-corroboration that the substantial-four-winds-gathering at Matt 24:31 is the substantial-paternal-blood-remnant-of-the-twelve-tribes the prophets walked the substantial-substance-for at Deuteronomy 30:1-4 + Isaiah 11:11-12 + Isaiah 27:12-13 + Jeremiah 23:3 + Jeremiah 31:8-10 + Ezekiel 11:17 + Ezekiel 20:34, 41 + Ezekiel 34:11-16 + Ezekiel 36:24 + Ezekiel 37:21 + Hosea 1:10-11 + Micah 2:12 + Micah 4:6-7 + Zephaniah 3:19-20 + Zechariah 8:7-8 + Zechariah 10:8-10. NOT the substantial-spiritual-category-substance the substantial-Christian-inclusion-gospel walks; the substantial-elect is the substantial-paternal-blood-remnant the substantial-substance preserved-from-the-foundation-of-the-world per Revelation 13:8 + Revelation 17:8.',
       sv.verse_id, ev.verse_id, 'complete_study', 343
  FROM _s156_xref_lookup sv, _s156_xref_lookup ev
 WHERE sv.edition_slug = 'canon' AND sv.book_slug = 'matthew' AND sv.chapter_number = 24 AND sv.verse_number = 27
   AND ev.edition_slug = 'canon' AND ev.book_slug = 'matthew' AND ev.chapter_number = 24 AND ev.verse_number = 31
ON CONFLICT (slug) DO NOTHING;

