-- ---------------------------------------------------------------------
-- Verification block.
-- ---------------------------------------------------------------------
DO $verify$
DECLARE
  v_xref_inserted INT;
  v_thread_inserted INT;
  v_member_inserted INT;
BEGIN
  SELECT count(*) INTO v_xref_inserted FROM cross_references x
    JOIN _s156_xref_lookup sv ON sv.verse_id = x.source_verse_id
   WHERE sv.edition_slug = 'canon' AND sv.book_slug = 'matthew' AND sv.chapter_number = 24
     AND x.tier_required = 'extras' AND x.source = 'manual';

  SELECT count(*) INTO v_thread_inserted FROM cross_reference_threads
   WHERE slug IN (
     'the-days-of-noach-and-the-watcher-rebellion-judgment-pattern-in-1-enoch-and-jubilees',
     'the-gathering-of-the-elect-from-the-four-winds-in-1-enochs-animal-apocalypse-and-parables',
     'the-signs-of-the-end-and-the-ten-tribes-gathered-in-2-esdras',
     'the-faithful-and-wise-servant-and-the-day-of-visitation-in-sirach-and-wisdom-of-solomon',
     'the-mount-of-olives-vision-and-the-gathering-of-the-tribes-in-testaments-of-naphtali-and-asher'
   );

  SELECT count(*) INTO v_member_inserted
    FROM cross_reference_thread_members m
    JOIN cross_reference_threads t ON t.id = m.thread_id
   WHERE t.slug IN (
     'the-days-of-noach-and-the-watcher-rebellion-judgment-pattern-in-1-enoch-and-jubilees',
     'the-gathering-of-the-elect-from-the-four-winds-in-1-enochs-animal-apocalypse-and-parables',
     'the-signs-of-the-end-and-the-ten-tribes-gathered-in-2-esdras',
     'the-faithful-and-wise-servant-and-the-day-of-visitation-in-sirach-and-wisdom-of-solomon',
     'the-mount-of-olives-vision-and-the-gathering-of-the-tribes-in-testaments-of-naphtali-and-asher'
   );

  RAISE NOTICE 'S156 Matt 24 verify: extras xrefs from canon/matthew/24 = %, threads = %, members = %',
    v_xref_inserted, v_thread_inserted, v_member_inserted;

  IF v_thread_inserted <> 5 THEN
    RAISE EXCEPTION 'Expected 5 threads inserted; got %', v_thread_inserted;
  END IF;
  IF v_xref_inserted < 21 THEN
    RAISE EXCEPTION 'Expected at least 21 Matt-24 extras xrefs; got %', v_xref_inserted;
  END IF;
  IF v_member_inserted < 21 THEN
    RAISE EXCEPTION 'Expected at least 21 thread members; got %', v_member_inserted;
  END IF;
END;
$verify$;

COMMIT;
